go
func (kr *KRun) go() error {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Handle termination signals
	signalChan := make(chan os.Signal, 1)
	signal.Notify(signalChan, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-signalChan
		cancel()
	}()

	// Initialize the application
	if err := kr.initialize(ctx); err != nil {
		return fmt.Errorf("failed to initialize KRun: %w", err)
	}

	// Start the application
	if err := kr.startApp(ctx); err != nil {
		return fmt.Errorf("failed to start application: %w", err)
	}

	// Wait for application to finish
	select {
	case <-ctx.Done():
		log.Println("KRun context canceled, shutting down...")
		if err := kr.shutdown(); err != nil {
			return fmt.Errorf("failed to shutdown KRun: %w", err)
		}
	case err := <-kr.appCmd.Wait():
		if err != nil {
			return fmt.Errorf("application exited with error: %w", err)
		}
		log.Println("Application exited successfully")
	}

	return nil
}

