func (kr *KRun) go() error {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	signalChan := make(chan os.Signal, 1)
	signal.Notify(signalChan, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		<-signalChan
		cancel()
	}()

	// Load necessary configurations
	if err := kr.loadConfigurations(ctx); err != nil {
		return fmt.Errorf("failed to load configurations: %w", err)
	}

	// Start the application and the agent
	if err := kr.startComponents(ctx); err != nil {
		return fmt.Errorf("failed to start components: %w", err)
	}

	// Wait for the application to be ready
	if err := kr.waitForAppReady(ctx); err != nil {
		return fmt.Errorf("application is not ready: %w", err)
	}

	// Monitor application and agent for any errors
	if err := kr.monitorComponents(ctx); err != nil {
		return fmt.Errorf("error monitoring components: %w", err)
	}

	return nil
}

