func pack(inputs ...interface{}) ([]byte, error) {
	var packed []byte
	for _, input := range inputs {
		switch v := input.(type) {
		case bool:
			packed = append(packed, byte(0x01))
			if !v {
				packed[len(packed)-1] = 0x00
			}
		case int, int8, int16, int32, int64:
			num := big.NewInt(reflect.ValueOf(v).Int())
			packed = append(packed, num.Bytes()...)
		case uint, uint8, uint16, uint32, uint64:
			num := big.NewInt(reflect.ValueOf(v).Uint())
			packed = append(packed, num.Bytes()...)
		case *big.Int:
			packed = append(packed, v.Bytes()...)
		case string:
			packed = append(packed, []byte(v)...)
		default:
			return nil, fmt.Errorf("unsupported type: %T", input)
		}
	}
	return packed, nil
}

