return true
}

type controlBuffer struct {
	mu    sync.Mutex
	items []interface{}
}

func (cb *controlBuffer) add(item interface{}) {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.items = append(cb.items, item)
}

func (cb *controlBuffer) take() interface{} {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	if len(cb.items) == 0 {
		return nil
	}
	item := cb.items[0]
	cb.items = cb.items[1:]
	return item
}

func (cb *controlBuffer) isEmpty() bool {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	return len(cb.items) == 0
}

