type controlBuffer struct {
	mu    sync.Mutex
	items []item
}

func (cb *controlBuffer) put(i item) {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.items = append(cb.items, i)
}

func (cb *controlBuffer) get() item {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	if len(cb.items) == 0 {
		return nil
	}
	i := cb.items[0]
	cb.items = cb.items[1:]
	return i
}

func (cb *controlBuffer) isEmpty() bool {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	return len(cb.items) == 0
}

