								Value: ".cluster.local",
							},
						},
					},
					JenkinsPipelineStrategy: &buildapiv1.JenkinsPipelineBuildStrategy{
						Env: []corev1.EnvVar{
							{
								Name:  "HTTP_PROXY",
								Value: "http://user:password@proxy.com",
