go
	"fmt"
	"os"
	"path/filepath"
)

func go() {
	// Define the configuration directory
	configDir := "./config"

	// Create a buffer to hold the configuration data
	var configBuffer bytes.Buffer

	// Walk through the configuration directory
	err := filepath.Walk(configDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if !info.IsDir() {
			// Read the file content
			data, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			// Write the content to the buffer
			configBuffer.Write(data)
			configBuffer.WriteString("\n")
		}
		return nil
	})

	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading config files: %v\n", err)
		return
	}

	// Output the combined configuration
	fmt.Println(configBuffer.String())
}

