func (s *Store) go() {
    ticker := time.NewTicker(defaultDefaultTTL)
    defer ticker.Stop()

    for {
        select {
        case <-ticker.C:
            s.cleanupExpiredEntries()
        }
    }
}

func (s *Store) cleanupExpiredEntries() {
    now := time.Now()
    expiredEntries := s.getExpiredEntries(now)

    for _, entry := range expiredEntries {
        s.removeEntry(entry)
    }
}

func (s *Store) getExpiredEntries(now time.Time) []Entry {
    var expired []Entry
    for _, entry := range s.entries {
        if entry.Expiration.Before(now) {
            expired = append(expired, entry)
        }
    }
    return expired
}

func (s *Store) removeEntry(entry Entry) {
    delete(s.entries, entry.ID)
}

