func (s *Store) go() {
	// Initialize the database connection and start the replication process
	db, err := database.NewConnection(s.config.DatabaseURL)
	if err != nil {
		s.logger.Fatalf("Failed to connect to the database: %v", err)
	}
	defer db.Close()

	// Set up a ticker to periodically check for updates
	ticker := time.NewTicker(defaultMinimumTTL)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			if err := s.updateConfig(db); err != nil {
				s.logger.Errorf("Failed to update configuration: %v", err)
			}
		case <-s.stopCh:
			s.logger.Info("Stopping the configuration update process.")
			return
		}
	}
}

func (s *Store) updateConfig(db *database.Connection) error {
	// Fetch the latest configuration from the database
	config, err := db.FetchLatestConfig()
	if err != nil {
		return err
	}

	// Update the local in-memory state with the fetched configuration
	s.configMutex.Lock()
	s.currentConfig = config
	s.configMutex.Unlock()

	// Trigger any necessary replication of the new configuration
	return s.replicateConfig(config)
}

